import json
from strings import G, C, dump, OUT
FAM = G('أَهْلِكَ', 'أَهْلِكِ'); TOUCH = G('اِلْمَسْ', 'اِلْمَسِي'); TOUCH_ = G('اِلْمَسِ', 'اِلْمَسِي'); WITHYOU = G('مَعَكَ', 'مَعَكِ'); LOOK = G('اُنْظُرْ', 'اُنْظُرِي')
PUT_ = G('ضَعِ', 'ضَعِي'); PRED = G('تَوَقَّعْ', 'تَوَقَّعِي'); TAPIT = G('اِلْمَسْهُ', 'اِلْمَسِيهِ'); TAPHER = G('اِلْمَسْهَا', 'اِلْمَسِيهَا')
DONE = 'ثُمَّ ' + TOUCH + ' «تَمَّ».'
KID = lambda m, f: G(m, f)   # الطفل المرسوم بصورة الطفل نفسه: الضمير يتبع جنسه
def where(q, ref, thing, at, words, **k): return {'t': 'where', 'q': q, 'pic': {'ref': ref, 'thing': thing, 'at': at}, 'words': words, **k}   # words لا opts: opts قائمة مولّدات في فحص المحتوى
def whereThing(q, ref, put, want, **k): return {'t': 'where', 'ask': 'thing', 'q': q, 'pic': {'ref': ref, 'put': put}, 'want': want, **k}
def place(q, ref, thing, at, **k): return {'t': 'place', 'q': q, 'ref': ref, 'thing': thing, 'at': at, **k}
def qplace(q, members, thing, at, **k): return {'t': 'place', 'q': q, 'ref': 'queue', 'members': members, 'thing': thing, 'at': at, **k}
def queue(q, members, ask, **k): return {'t': 'lineTap', 'q': q, 'row': {'kind': 'queue', 'members': members}, 'ask': ask, **k}
def car(q, n, k, things=None, **x): return {'t': 'lineTap', 'q': q, 'row': {'kind': 'train', 'n': n, **({'things': things} if things else {})}, 'ask': 'ord', 'k': k, **x}
def which(q, n, k, thing, opts, **x): return {'t': 'linePick', 'q': q, 'row': {'kind': 'train', 'n': n, 'things': {str(k): thing}}, 'k': k, 'opts': opts, **x}
def lrTap(q, side, up=None, **k): return {'t': 'lrTap', 'q': q, 'side': side, **({'raise': up} if up else {}), **k}   # up: اليد المرفوعة (raise كلمة محجوزة في بايثون)
def lrPick(q, thing, side, **k): return {'t': 'lrPick', 'q': q, 'thing': thing, 'side': side, **k}
def robot(q, prog, **k): return {'t': 'robot', 'q': q, 'prog': list(prog), **k}
def watch(q, prog, ok, bad, err='rbTurnMove'): return {'t': 'robotWatch', 'q': q, 'prog': list(prog), 'opts': [{'id': ok, 'ok': True}, {'id': bad, 'err': err}]}
def mfind(q, lay, mark, **k): return {'t': 'mapFind', 'q': q, 'lay': lay, 'mark': mark, **k}   # mark: {k, cell:[عمود، صفّ]} على الأرض، أو {k, on, rel} فوق شيء أو تحته
def cell(k, col, row): return {'k': k, 'cell': [col, row]}
def on(k, id_, rel='on'): return {'k': k, 'on': id_, 'rel': rel}
def mput(q, lay, want, cands): return {'t': 'mapPut', 'q': q, 'lay': lay, 'want': want, 'cands': cands}
def walk(q, a, b, **k): return {'t': 'roadHop', 'q': q, 'a': a, 'b': b, **k}
def jump(q, a, n, d=1, **k): return {'t': 'roadHop', 'q': q, 'a': a, 'n': n, **({'dir': -1} if d < 0 else {}), **k}
def rpick(q, n, ask, **k): return {'t': 'roadPick', 'q': q, 'n': n, 'ask': ask, **k}
def lay(door, win, *items): return {'door': door, 'win': win, 'items': [dict(zip(('k', 'col', 'row'), i)) if len(i) == 3 else dict(zip(('k', 'col', 'row', 'id'), i)) for i in items]}

