# ======================= التوأم (الفحص المستقل B: لم يكن في الوحدة توأم) =======================
# بعد الحلّ المشترك أو الكشف في التمرين والعلاج واللعب يأتي بند توأم (40_items.js، المبدأ 5): المهارة نفسها في صورة أخرى، يحلّها الطفل وحده.
# لكل درس مستودع بالمهارة، ويُختار لكل بند أول مرشّح مسألته غير مسألة الأصل؛ ومسائل التوأم «معروضة» في d240 فلا يقيسها تقييم، ولا توأم للتوأم
def _pk(a): return 'beside' if a and a.startswith('beside') else a
def skill(it):
    t = it['t']
    if t == 'place' and it.get('ref') == 'queue':
        i, n = int(it['at'][1:]), len(it['members']); return 'qplace|' + ('front' if i == 0 else 'behind' if i == n else 'between')
    if t in ('where', 'place'):
        ref = it.get('ref') or it['pic']['ref']; w = it.get('want') or (it['at'] if t == 'place' else it['pic']['at'])
        return 'regions' if ref == 'regions' else 'pos|' + _pk(w)
    if t == 'lineTap': return 'line|' + it['row']['kind'] + '|' + it['ask']
    if t == 'lrTap': return 'lrTap|' + it.get('ask', 'hand')
    if t == 'roadHop': return ('walk' if 'b' in it else 'jump') + ('-' if it.get('dir') == -1 or ('b' in it and it['b'] < it['a']) else '+')
    if t == 'roadPick': return 'rpick|' + it['ask']
    if t == 'mapFind': return 'mapFind|' + ('cell' if 'cell' in it['mark'] else 'on')
    return t
def fact(it):   # مفتاح المسألة كما في build/d240.mjs (للمقارنة هنا فقط؛ والفحص الحاسم هناك)
    t = it['t']; J = lambda v: json.dumps(v, ensure_ascii=False, sort_keys=True)
    if t == 'place': return 'pos|place|queue|%s|%d' % (it['at'], len(it['members'])) if it.get('ref') == 'queue' else 'pos|place|%s|%s' % (it['ref'], _pk(it['at']))
    if t == 'where': return 'pos|thing|%s|%s' % (it['pic']['ref'], _pk(it['want'])) if it.get('ask') == 'thing' else 'pos|where|%s|%s' % (it['pic']['ref'], _pk(it['pic']['at']))
    if t in ('lineTap', 'linePick') and it['row']['kind'] == 'train': return 'kamAyn|%d' % it['k'] if it.get('ask') == 'kamAyn' else 'ord|%s|%d' % ('pick' if t == 'linePick' else 'tap', it['k'])
    if t == 'lineTap' and it['ask'] == 'ord': return 'ordm|tap|%d' % it['k']
    if t == 'lineTap': return 'line|%d|%s|%s' % (len(it['row']['members']), it['ask'], ','.join(str(it[k]) for k in ('ref', 'a', 'b', 'ans') if k in it))
    if t in ('lrTap', 'lrPick'): return 'lr|%s|%s|%s|%d' % ('side' if t == 'lrPick' else it.get('ask', 'hand'), it['side'], it.get('raise', ''), 0 if it.get('ribbon') is False else 1)
    if t in ('robot', 'robotWatch'): return 'robot|' + ''.join(it['prog']) + '|' + J(it.get('start', {}))
    if t == 'mapFind':
        m = it['mark']; c = m['cell'] if 'cell' in m else next([i['col'], i['row']] for i in it['lay']['items'] if i.get('id', i['k']) == m['on'])
        return 'map|find|' + J(it['lay']) + '|' + str(c) + ('' if 'cell' in m else '|' + m.get('rel', 'on'))
    if t == 'mapPut': return 'map|put|' + J(it['lay']) + '|' + it['want']
    if t == 'routePick': return 'route|' + J(it['lay'])
    if t == 'roadHop': return 'walk|%d|%d' % (it['a'], it['b']) if 'b' in it else 'jump|%d|%d' % (it['a'], it.get('dir', 1) * it['n'])
    if t == 'roadPick':
        if it['ask'] == 'land': return 'jump|%d|%d' % (it['n'], it.get('dir', 1) * it['k'])
        if it['ask'] == 'hops': return 'jump|%d|%d' % (it['n'], it['b'] - it['n'])
        return ('succ|' if it['ask'] in ('next', 'more') else 'pred|') + str(it['n'])
    return None
